import { useId, useState } from "react";
import type { AngleMode } from "../api/types";
import { CalcButton } from "./CalcButton";
import { AngleModeToggle } from "./AngleModeToggle";
import "./ScientificKeypad.css";

/**
 * Props for {@link ScientificKeypad}.
 *
 * Like the Stage 1 {@link import("./Keypad").Keypad}, the ScientificKeypad is
 * presentational: it renders every scientific control and routes activations to
 * the callbacks the Calculator container (task 35.3) supplies. It computes no
 * arithmetic and owns no app/calculation state (Requirement 14.1). The only
 * local state it holds is the purely-visual `collapsed` flag for its mobile
 * collapse/expand affordance (Requirements 22.2, 22.8).
 */
export interface ScientificKeypadProps {
  /**
   * Appends a token to the current expression. For functions the token is the
   * opener form matching the keyboard/engine grammar (e.g. `"sin("`, `"ln("`,
   * `"sqrt("`, `"root("`); for constants it is `"pi"` / `"e"` (Requirements
   * 19.3, 19.4); for the power operator it is `"^"`. Tokens are emitted
   * deterministically — the same control always contributes the same text
   * (Requirement 19.5).
   */
  onInput: (token: string) => void;
  /** The currently active angle unit, passed through to the hosted toggle. */
  angleMode: AngleMode;
  /** Requests an angle-mode flip; passed through to the hosted toggle (Requirements 22.1, 22.7). */
  onToggleAngleMode: () => void;
  /** Adds the current value to the Memory_Register (M+). */
  onMemoryAdd: () => void;
  /** Subtracts the current value from the Memory_Register (M-). */
  onMemorySubtract: () => void;
  /** Recalls the Memory_Register into the expression (MR). */
  onMemoryRecall: () => void;
  /** Clears the Memory_Register (MC). */
  onMemoryClear: () => void;
}

/**
 * Describes a single token-emitting control rendered in the scientific keypad.
 */
interface SciKeyDef {
  /** Visible label shown inside the button (Requirement 11.6). */
  label: string;
  /** Spoken accessible label describing the control's function (Requirements 12.1, 12.2). */
  ariaLabel: string;
  /** The deterministic token text appended to the expression (Requirement 19.5). */
  token: string;
  /** `grid-area` name assigned to this control in `ScientificKeypad.css`. */
  area: string;
}

/**
 * Trigonometric functions. Each appends its opener form so the engine grammar
 * sees e.g. `sin(` (Requirements 17.1, 19.5).
 */
const TRIG_KEYS: readonly SciKeyDef[] = [
  { label: "sin", ariaLabel: "sine", token: "sin(", area: "sin" },
  { label: "cos", ariaLabel: "cosine", token: "cos(", area: "cos" },
  { label: "tan", ariaLabel: "tangent", token: "tan(", area: "tan" },
];

/**
 * Inverse trigonometric functions. Visible labels use the conventional
 * superscript-inverse notation; accessible labels spell the function out
 * (Requirement 12.1).
 */
const INVERSE_TRIG_KEYS: readonly SciKeyDef[] = [
  { label: "sin⁻¹", ariaLabel: "inverse sine", token: "asin(", area: "asin" },
  { label: "cos⁻¹", ariaLabel: "inverse cosine", token: "acos(", area: "acos" },
  { label: "tan⁻¹", ariaLabel: "inverse tangent", token: "atan(", area: "atan" },
];

/** Logarithm, root, power and constant controls. */
const FUNCTION_KEYS: readonly SciKeyDef[] = [
  { label: "ln", ariaLabel: "natural logarithm", token: "ln(", area: "ln" },
  { label: "log", ariaLabel: "base-10 logarithm", token: "log10(", area: "log10" },
  { label: "√", ariaLabel: "square root", token: "sqrt(", area: "sqrt" },
  { label: "ʸ√x", ariaLabel: "nth root", token: "root(", area: "root" },
  { label: "xʸ", ariaLabel: "power exponent", token: "^", area: "pow" },
  { label: "π", ariaLabel: "pi constant", token: "pi", area: "pi" },
  { label: "e", ariaLabel: "e constant", token: "e", area: "e" },
];

/**
 * Describes a single memory control, wired to its own callback rather than a
 * token (Requirement 22.1 — the keypad renders the memory CONTROLS; the badge
 * indicator lives near the display and is the container's call).
 */
interface MemoryKeyDef {
  label: string;
  ariaLabel: string;
  area: string;
}

const MEMORY_KEYS: readonly MemoryKeyDef[] = [
  { label: "M+", ariaLabel: "memory add", area: "madd" },
  { label: "M-", ariaLabel: "memory subtract", area: "msub" },
  { label: "MR", ariaLabel: "memory recall", area: "mrecall" },
  { label: "MC", ariaLabel: "memory clear", area: "mclear" },
];

/**
 * The scientific-functions keypad.
 *
 * Renders, via the shared {@link CalcButton}, the trig / inverse-trig
 * functions, `ln`/`log10`, `sqrt`/`root`, the power operator, the `pi`/`e`
 * constants, and the M+/M-/MR/MC memory controls (Requirements 17.x, 18.x,
 * 19.3-19.5, 22.1). It also HOSTS the {@link AngleModeToggle}, passing through
 * the `angleMode`/`onToggleAngleMode` props (Requirement 22.1).
 *
 * The panel is collapsible so it can be hidden on narrow viewports (Requirements
 * 22.2, 22.8). A dedicated collapse/expand control carries `aria-expanded`
 * reflecting the current state and `aria-controls` referencing the controls
 * region; when collapsed the region is removed from the accessibility tree and
 * layout via the native `hidden` attribute. The `collapsed` flag is purely
 * visual UI state held locally with `useState` — it is not app/calculation
 * state. The responsive rule that makes the collapse affordance apply only at
 * mobile widths (Requirement 22.2) plus the >=44px touch targets (22.5) and
 * contrast (11.x) are finalized by the styling task (task 36); this component
 * provides the collapse control, `aria-expanded`, and a `.scientific-keypad`
 * class hook.
 */
export function ScientificKeypad({
  onInput,
  angleMode,
  onToggleAngleMode,
  onMemoryAdd,
  onMemorySubtract,
  onMemoryRecall,
  onMemoryClear,
}: ScientificKeypadProps) {
  const [collapsed, setCollapsed] = useState(false);
  // Stable id so the collapse control's `aria-controls` references the region.
  const regionId = useId();

  const memoryHandlers: Record<string, () => void> = {
    madd: onMemoryAdd,
    msub: onMemorySubtract,
    mrecall: onMemoryRecall,
    mclear: onMemoryClear,
  };

  return (
    <div className="scientific-keypad" role="group" aria-label="scientific functions">
      <div className="scientific-keypad__header">
        <AngleModeToggle angleMode={angleMode} onToggle={onToggleAngleMode} />
        <CalcButton
          label={collapsed ? "Show ▸" : "Hide ▾"}
          ariaLabel="Scientific functions"
          variant="action"
          className="scientific-keypad__collapse"
          onActivate={() => setCollapsed((prev) => !prev)}
        />
      </div>

      <div
        id={regionId}
        className="scientific-keypad__controls"
        hidden={collapsed}
      >
        {[...TRIG_KEYS, ...INVERSE_TRIG_KEYS, ...FUNCTION_KEYS].map((key) => (
          <CalcButton
            key={key.area}
            label={key.label}
            ariaLabel={key.ariaLabel}
            variant="action"
            className={`scientific-keypad__key scientific-keypad__key--${key.area}`}
            onActivate={() => onInput(key.token)}
          />
        ))}

        {MEMORY_KEYS.map((key) => (
          <CalcButton
            key={key.area}
            label={key.label}
            ariaLabel={key.ariaLabel}
            variant="action"
            className={`scientific-keypad__key scientific-keypad__key--${key.area}`}
            onActivate={memoryHandlers[key.area]}
          />
        ))}
      </div>
    </div>
  );
}

export default ScientificKeypad;

/*
 * Structural layout for the Scientific_Keypad (Requirements 22.1, 22.2, 22.8).
 *
 * This file owns only the grid *structure* and the collapse class hook. The
 * responsive breakpoints that make the collapse affordance apply only at mobile
 * widths (Requirement 22.2), the >= 44x44px touch targets (22.5), and the
 * contrast-compliant theme (11.x) are finalized by the styling task (task 36).
 * A reasonable default grid is provided here so the panel is usable in the
 * meantime.
 */

.scientific-keypad {
  display: flex;
  flex-direction: column;
  gap: var(--gap, 0.5rem);
  width: 100%;
}

/* Header row: angle-mode toggle on the left, collapse/expand control on the right. */
.scientific-keypad__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--gap, 0.5rem);
}

/*
 * The collapsible controls region. `hidden` (set by the component when
 * collapsed) removes it from layout and the accessibility tree; this class is
 * the hook task 36 uses to scope the collapse behavior to mobile widths.
 */
.scientific-keypad__controls {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: minmax(var(--touch-min, 44px), auto);
  gap: var(--gap, 0.5rem);
}

/* The native `hidden` attribute must win over the grid display above. */
.scientific-keypad__controls[hidden] {
  display: none;
}

.scientific-keypad__collapse {
  white-space: nowrap;
}

import type { CalculationHistory } from "../api/types";
import { isHistoryEmpty } from "../state/historyReducer";
import { CalcButton } from "./CalcButton";
import "./HistoryPanel.css";

/**
 * Props for {@link HistoryPanel}.
 *
 * Presentational component: the Calculator container (task 35.3) owns the
 * Calculation_History state (via `historyReducer`) and the selection logic. This
 * panel only renders the entries it is handed and routes activations to the
 * supplied callbacks; it holds no state and performs no arithmetic.
 */
export interface HistoryPanelProps {
  /**
   * The session Calculation_History, already ordered newest-first by the
   * reducer. The panel renders it in the given order (Requirement 21.2).
   */
  history: CalculationHistory;
  /**
   * Loads the selected entry's expression into the current expression
   * (Requirement 21.3). Called with the entry's `expression` string.
   */
  onSelectExpression: (expression: string) => void;
  /**
   * Loads the selected entry's result into the current expression
   * (Requirement 21.4). Called with the entry's `result` string.
   */
  onSelectResult: (result: string) => void;
  /** Clears the entire Calculation_History (Requirement 21.6). */
  onClear: () => void;
}

/**
 * A side panel listing the session's completed calculations.
 *
 * - Rendered as an `<aside role="complementary">` with an accessible name
 *   "calculation history" so assistive technologies can locate the region.
 * - Lists entries newest-first in the order supplied (Requirement 21.2).
 * - For each entry the expression and the result are two INDEPENDENTLY
 *   selectable controls: activating the expression calls
 *   {@link HistoryPanelProps.onSelectExpression}; activating the result calls
 *   {@link HistoryPanelProps.onSelectResult} (Requirements 21.3, 21.4). Both
 *   reuse {@link CalcButton}, inheriting its visible-label + matching-aria-label
 *   and focus/pressed states (Requirements 11.6, 12.1, 12.2).
 * - A Clear History control calls {@link HistoryPanelProps.onClear}
 *   (Requirement 21.6); it is disabled when the history is empty.
 * - When the history is empty an empty-state message is shown instead of the
 *   list (Requirement 21.8).
 *
 * List keys: history entries can duplicate (the same expression/result pair can
 * recur), so there is no stable natural key. The list is append-only and capped
 * (MAX_HISTORY), and entries are never reordered in place, so the array index is
 * an acceptable, stable-enough key here. Contrast/responsive drawer behavior is
 * finalized by the styling task (task 36).
 */
export function HistoryPanel({
  history,
  onSelectExpression,
  onSelectResult,
  onClear,
}: HistoryPanelProps) {
  const empty = isHistoryEmpty(history);

  return (
    <aside
      className="history-panel"
      role="complementary"
      aria-label="calculation history"
    >
      <div className="history-panel__header">
        <h2 className="history-panel__title">History</h2>
        <CalcButton
          label="Clear"
          ariaLabel="clear history"
          variant="action"
          className="history-panel__clear"
          onActivate={onClear}
          disabled={empty}
        />
      </div>

      {empty ? (
        <p className="history-panel__empty">No calculations yet.</p>
      ) : (
        <ul className="history-panel__list">
          {history.map((entry, index) => (
            <li key={index} className="history-panel__item">
              <CalcButton
                label={entry.expression}
                ariaLabel={`Load expression ${entry.expression}`}
                variant="digit"
                className="history-panel__expression"
                onActivate={() => onSelectExpression(entry.expression)}
              />
              <CalcButton
                label={`= ${entry.result}`}
                ariaLabel={`Load result ${entry.result}`}
                variant="operator"
                className="history-panel__result"
                onActivate={() => onSelectResult(entry.result)}
              />
            </li>
          ))}
        </ul>
      )}
    </aside>
  );
}

export default HistoryPanel;

/*
 * Structural layout for the History_Panel drawer (Requirements 21.2-21.8).
 *
 * This file owns only the drawer/list *structure*. The contrast-compliant theme
 * (11.x) and the responsive drawer behavior (collapsing/overlaying at mobile
 * widths) are finalized by the styling task (task 36). A reasonable default is
 * provided here so the panel is usable in the meantime.
 */

.history-panel {
  display: flex;
  flex-direction: column;
  gap: var(--gap, 0.5rem);
  width: 100%;
  min-width: 0;
}

.history-panel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--gap, 0.5rem);
}

.history-panel__title {
  margin: 0;
  font-size: 1rem;
}

/* Empty-state message shown when there are no entries (Requirement 21.8). */
.history-panel__empty {
  margin: 0;
  opacity: 0.8;
}

/* Newest-first list of entries (Requirement 21.2). */
.history-panel__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--gap, 0.5rem);
  overflow-y: auto;
}

/*
 * Each entry exposes two independently selectable controls: the expression and
 * the result (Requirements 21.3, 21.4). They stack within the row and each
 * fills the available width so both are comfortable touch targets.
 */
.history-panel__item {
  display: flex;
  flex-direction: column;
  gap: calc(var(--gap, 0.5rem) / 2);
}

.history-panel__expression,
.history-panel__result {
  width: 100%;
  text-align: right;
  overflow-wrap: anywhere;
}
